136	      List<ContainerBlockInfo> containers =
137	          chooseContainerForBlockDeletion(getBlockLimitPerInterval(),
138	              containerDeletionPolicy);
139	
140	      BackgroundTask
141	          containerBlockInfos = null;
142	      long totalBlocks = 0;
143	      for (ContainerBlockInfo containerBlockInfo : containers) {
144	        BlockDeletingTaskBuilder builder =
145	            new BlockDeletingTaskBuilder();
146	        builder.setBlockDeletingService(this)
147	            .setContainerBlockInfo(containerBlockInfo)
148	            .setPriority(TASK_PRIORITY_DEFAULT);
149	        containerBlockInfos = builder.build();
150	        queue.add(containerBlockInfos);
151	        totalBlocks += containerBlockInfo.getNumBlocksToDelete();
152	      }
153	      metrics.incrTotalBlockChosenCount(totalBlocks);
154	      metrics.incrTotalContainerChosenCount(containers.size());
155	      if (containers.size() > 0) {
156	        LOG.debug("Queued {} blocks from {} containers for deletion",
157	            totalBlocks, containers.size());
158	      }
