73	    // Compute checksums and return the result.
74	    ContainerProtos.ContainerMerkleTree.Builder containerTreeBuilder = ContainerProtos.ContainerMerkleTree.newBuilder();
75	    ChecksumByteBuffer checksumImpl = ChecksumByteBufferFactory.crc32Impl();
76	    ByteBuffer containerChecksumBuffer = ByteBuffer.allocate(Long.BYTES * id2Block.size());
77	
78	    for (BlockMerkleTree blockTree: id2Block.values()) {
79	      ContainerProtos.BlockMerkleTree blockTreeProto = blockTree.toProto();
80	      containerTreeBuilder.addBlockMerkleTree(blockTreeProto);
81	      // Add the block's checksum to the buffer that will be used to calculate the container checksum.
82	      containerChecksumBuffer.putLong(blockTreeProto.getBlockChecksum());
83	    }
84	    containerChecksumBuffer.flip();
85	    checksumImpl.update(containerChecksumBuffer);
