46	public class ContainerChecksumTreeManager {
47	
48	  private static final Logger LOG = LoggerFactory.getLogger(ContainerChecksumTreeManager.class);
49	
50	  // Used to coordinate reads and writes to each container's checksum file.
51	  // Each container ID is mapped to a stripe.
52	  private final Striped<ReadWriteLock> fileLock;
53	  private final ContainerMerkleTreeMetrics metrics;
54	
55	  /**
56	   * Creates one instance that should be used to coordinate all container checksum info within a datanode.
57	   */
58	  public ContainerChecksumTreeManager(ConfigurationSource conf) {
59	    DatanodeConfiguration dnConf = conf.getObject(DatanodeConfiguration.class);
60	    fileLock = SimpleStriped.readWriteLock(dnConf.getContainerChecksumLockStripes(), true);
61	    // TODO: TO unregister metrics on stop.
62	    metrics = ContainerMerkleTreeMetrics.create();
63	  }
64	
65	  /**
66	   * Writes the specified container merkle tree to the specified container's checksum file.
67	   * The data merkle tree within the file is replaced with the {@code tree} parameter, but all other content of the
68	   * file remains unchanged.
69	   * Concurrent writes to the same file are coordinated internally.
70	   */
71	  public void writeContainerDataTree(KeyValueContainerData data, ContainerMerkleTree tree) throws IOException {
72	    Lock writeLock = getWriteLock(data.getContainerID());
73	    writeLock.lock();
74	    try {
75	      ContainerProtos.ContainerChecksumInfo newChecksumInfo = read(data).toBuilder()
76	          .setContainerMerkleTree(captureLatencyNs(metrics.getCreateMerkleTreeLatencyNS(), tree::toProto))
77	          .build();
78	      write(data, newChecksumInfo);
79	      LOG.debug("Data merkle tree for container {} updated", data.getContainerID());
80	    } finally {
81	      writeLock.unlock();
82	    }
83	  }
84	
85	  /**
86	   * Adds the specified blocks to the list of deleted blocks specified in the container's checksum file.
87	   * All other content of the file remains unchanged.
88	   * Concurrent writes to the same file are coordinated internally.
89	   */
90	  public void markBlocksAsDeleted(KeyValueContainerData data, Collection<Long> deletedBlockIDs) throws IOException {
91	    Lock writeLock = getWriteLock(data.getContainerID());
92	    writeLock.lock();
93	    try {
94	      ContainerProtos.ContainerChecksumInfo.Builder checksumInfoBuilder = read(data).toBuilder();
95	      // Combine the previously persisted deleted block IDs with the new ones.
96	      // Using a sorted set deduplicates the entries and keeps them sorted, so that the persisted list always
97	      // reflects all deletions in sorted, deduplicated order even across multiple (possibly retried) calls.
98	      SortedSet<Long> sortedDeletedBlockIDs = new TreeSet<>(checksumInfoBuilder.getDeletedBlocksList());
99	      sortedDeletedBlockIDs.addAll(deletedBlockIDs);
100	
101	      checksumInfoBuilder
102	          .clearDeletedBlocks()
103	          .addAllDeletedBlocks(sortedDeletedBlockIDs);
104	      write(data, checksumInfoBuilder.build());
105	      LOG.debug("Deleted block list for container {} updated", data.getContainerID());
106	    } finally {
107	      writeLock.unlock();
108	    }
109	  }
